def outcome(self, blue_crash, red_crash):
    if blue_crash and red_crash:
        return 'mutual_crash'
    if blue_crash:
        return 'own_crash'
    if red_crash:
        return 'enemy_crash'
    if self.attack[0] >= TARGET_FRAMES and self.attack[1] >= TARGET_FRAMES:
        return 'simultaneous_hit'
    if self.attack[0] >= TARGET_FRAMES:
        return 'kill'
    if self.attack[1] >= TARGET_FRAMES:
        return 'shot_down'
    return 'ongoing'
